input.content:
// Simple in-memory store simulating a user's notification preference.
// In a real app this would be a database call.
const store = {
  notificationsEnabled: false,
}

export function getNotificationPreference(): boolean {
  return store.notificationsEnabled
}

export function setNotificationPreference(value: boolean): void {
  store.notificationsEnabled = value
}

'use server'

import { revalidatePath } from 'next/cache'

import { getNotificationPreference, setNotificationPreference } from './data'

export async function toggleNotifications() {
  const current = getNotificationPreference()
  setNotificationPreference(!current)

  // Refresh the current page's cached data on-demand without redirecting.
  // This is Next.js's recommended way to revalidate the current route's
  // data from within a Server Action, so the updated preference is shown.
  revalidatePath('/')
}

